package ratelimit

import (
	"sync"
	"testing"
	"time"
)

func TestAllow_FullBucket(t *testing.T) {
	lb := NewTokenBucket(5, 1.0) // capacity=5, refill=1/sec
	for i := 0; i < 5; i++ {
		if !lb.Allow() {
			t.Fatalf("expected Allow() true on attempt %d", i+1)
		}
	}
	if lb.Allow() {
		t.Fatal("bucket should be empty after 5 allows")
	}
}

func TestAllow_Refill(t *testing.T) {
	lb := NewTokenBucket(2, 10.0) // refill 10 tokens/sec
	lb.Allow()
	lb.Allow() // drain
	time.Sleep(150 * time.Millisecond) // ~1.5 tokens refilled
	if !lb.Allow() {
		t.Fatal("expected at least 1 token after refill")
	}
}

func TestAllow_NotExceedCapacity(t *testing.T) {
	lb := NewTokenBucket(3, 1000.0) // very fast refill
	time.Sleep(50 * time.Millisecond)
	// bucket should be capped at 3, not overflow
	count := 0
	for lb.Allow() {
		count++
	}
	if count != 3 {
		t.Fatalf("expected 3 (capacity), got %d", count)
	}
}

func TestAllow_Concurrent(t *testing.T) {
	lb := NewTokenBucket(100, 0) // no refill, 100 tokens
	var allowed int64
	var mu sync.Mutex
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if lb.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Fatalf("want 100 allowed, got %d", allowed)
	}
}

func TestAllow_ZeroCapacity(t *testing.T) {
	lb := NewTokenBucket(0, 0)
	if lb.Allow() {
		t.Fatal("zero capacity bucket should never allow")
	}
}

